import{_ as a,o as t,c as n,ae as o}from"./chunks/framework.BX6FPmO9.js";const g=JSON.parse('{"title":"Metadata Lineage Topological Sort","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/lineage-kahn.md","filePath":"architecture/lineage-kahn.md"}'),i={name:"architecture/lineage-kahn.md"};function r(d,e,c,l,s,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="metadata-lineage-topological-sort" tabindex="-1">Metadata Lineage Topological Sort <a class="header-anchor" href="#metadata-lineage-topological-sort" aria-label="Permalink to &quot;Metadata Lineage Topological Sort&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Metadata lineage edges model dependency direction as <code>source -&gt; target</code>: an upstream asset must be available before the asset that depends on it. T-2026-016 needs the lineage view to expose a dependency order when the graph is acyclic and reject cyclic lineage for ordering.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Use Kahn&#39;s topological sort in a pure TypeScript module at <code>app/lib/lineage/kahn.ts</code>.</p><p>The algorithm:</p><ol><li>Build an in-degree count for every lineage node.</li><li>Queue nodes with zero in-degree in stable input order.</li><li>Remove queued nodes one by one, appending them to the dependency order and decrementing their outgoing targets.</li><li>If every node is removed, the graph is acyclic and the order is valid.</li><li>If nodes remain with non-zero in-degree, the graph contains a cycle and no dependency order is returned.</li></ol><h2 id="ux-on-cycle" tabindex="-1">UX On Cycle <a class="header-anchor" href="#ux-on-cycle" aria-label="Permalink to &quot;UX On Cycle&quot;">​</a></h2><p><code>resolveMetadataLineage</code> returns <code>dependencyOrder</code> only when Kahn succeeds. When a cycle is detected, it returns <code>cycleError</code> with the affected node ids. <code>MetadataLineageGraph</code> renders this as an inline alert and hides the dependency order, while still showing the available lineage edges so data stewards can identify and fix the metadata relationship.</p>',9)])])}const u=a(i,[["render",r]]);export{g as __pageData,u as default};
